    comCinza = 0;
    emOnda = false;
    terminou = false;
    SZGame2D.forEachInGroup(ninhos, (ninho) => {
      SZGame2D.setSpriteData(ninho, "protegido", false);
      SZGame2D.setImage(ninho, "ninho");
    });
    SZGame2D.setSpriteData(ninho4, "protegido", false);
    SZGame2D.setImage(ninho4, "ninho");
    SZGame2D.setOpacity(cinza, 0);
    recado = "Toque nos ninhos para cobrir. Depois, Próxima onda.";
  }, "vale_lista_events_2");
  SZGame2D.onKey("Enter", () => {
    onda = 0;
    pontos = 0;
    protegidos = 0;
    comCinza = 0;
    emOnda = false;
    terminou = false;
    SZGame2D.forEachInGroup(ninhos, (ninho) => {
      SZGame2D.setSpriteData(ninho, "protegido", false);
      SZGame2D.setImage(ninho, "ninho");
    });
    SZGame2D.setSpriteData(ninho4, "protegido", false);
    SZGame2D.setImage(ninho4, "ninho");
    SZGame2D.setOpacity(cinza, 0);
    recado = "Toque nos ninhos para cobrir. Depois, Próxima onda.";
  }, "vale_lista_events_3");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    if (emOnda) {
      SZGame2D.applyVelocity(cinza);
      if (SZGame2D.spriteY(cinza) > 330) {
        SZGame2D.forEachInGroup(ninhos, (ninho) => {
          if (SZGame2D.spriteData(ninho, "protegido", false)) {
            SZGame2D.setImage(ninho, "ninho");
            protegidos = protegidos + 1;
            pontos = pontos + 1;
          } else {
            comCinza = comCinza + 1;
            SZGame2D.setImage(ninho, "cinzento");
          }
          SZGame2D.setSpriteData(ninho, "protegido", false);
        });
        emOnda = false;
        SZGame2D.setOpacity(cinza, 0);
        recado = "Prepare novas coberturas antes da próxima onda.";
        if (onda === totalDeOndas) {
          terminou = true;
          recado = "Ondas concluídas. Recomece para experimentar de novo.";
        }
      }
    }
    SZGame2D.clear();
    SZGame2D.drawBackdrop(ctx, "vale");
    SZGame2D.drawLabel(ctx, "Proteja os ninhos", 18, 32, "#233e40", 26, "left");
    SZGame2D.drawLabel(ctx, "Cubra cada ninho com folhas antes da cinza passar.", 18, 60, "#233e40", 17, "left");
    SZGame2D.forEachInGroup(ninhos, (ninho) => {
      if (SZGame2D.spriteData(ninho, "protegido", false)) {
        SZGame2D.setImage(ninho, "protegido");
      }
    });
    SZGame2D.drawGroup(ctx, ninhos);
    SZGame2D.drawSprite(ctx, ninho4);
    SZGame2D.drawSprite(ctx, cinza);
    SZGame2D.drawLabel(ctx, `Onda: ${onda}   Protegidos: ${protegidos}   Com cinza: ${comCinza}`, 18, 390, "#233e40", 18, "left");
    SZGame2D.drawLabel(ctx, `Pontos: ${pontos}`, 500, 32, "#233e40", 18, "left");
    SZGame2D.drawLabel(ctx, recado, 18, 411, "#233e40", 14, "left");
    if (emOnda === false && terminou === false) {
      SZGame2D.setOpacity(proxima, 100);
    } else {
      SZGame2D.setOpacity(proxima, 45);
    }
    SZGame2D.drawSprite(ctx, proxima);
    SZGame2D.drawSprite(ctx, reiniciar);
    SZGame2D.drawLabel(ctx, "Próxima onda", 139, 450, "#ffffff", 18, "left");
    SZGame2D.drawLabel(ctx, "Recomeçar", 375, 450, "#ffffff", 18, "left");
  }, "vale_lista_loops_0");
}, "__sz-project");
